from pathlib import Path
r=Path('opsagent-ts')
def w(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
w('tests/e2e/company.spec.ts',r'''import {test,expect} from '@playwright/test';
import {query} from '../../packages/db/src/index';
const base='http://127.0.0.1:3001';
test.beforeAll(async()=>{await query("UPDATE mock_portal.settings SET value='false' WHERE key='chaos'");});
async function login(page:import('@playwright/test').Page,system:string){await page.goto(base+'/'+system+'/login');await page.getByLabel('Username',{exact:true}).fill('demo');await page.getByLabel('Password',{exact:true}).fill('demo');await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page).toHaveURL(base+'/'+system);}
test('separate sessions, pagination, and real PDF download',async({page})=>{await login(page,'portal');await expect(page.locator('tbody tr')).toHaveCount(5);await page.getByRole('link',{name:'Next page',exact:true}).click();await expect(page.getByText('Page 2',{exact:true})).toBeVisible();await page.locator('tbody a').first().click();const [download]=await Promise.all([page.waitForEvent('download'),page.getByRole('link',{name:'Download PDF',exact:true}).click()]);expect(download.suggestedFilename()).toMatch(/\.pdf$/);await page.goto(base+'/erp');await expect(page).toHaveURL(base+'/erp/login');});
test('ERP validates, creates a real payable, and prevents duplicates',async({page})=>{await login(page,'erp');const number='TEST-'+Date.now();try{await page.getByRole('link',{name:'New payable',exact:true}).click();await page.locator('[name=number]').fill(number);await page.locator('[name=amount]').fill('123.45');await page.locator('[name=due]').fill('2026-10-20');await page.getByRole('button',{name:'Create payable',exact:true}).click();await expect(page.getByText(number,{exact:true})).toBeVisible();await page.getByRole('link',{name:'New payable',exact:true}).click();await page.locator('[name=number]').fill(number);await page.locator('[name=amount]').fill('123.45');await page.locator('[name=due]').fill('2026-10-20');await page.getByRole('button',{name:'Create payable',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Duplicate');await page.locator('[name=amount]').evaluate((el)=>{(el as HTMLInputElement).min='-100';});await page.locator('[name=amount]').fill('-1');await page.getByRole('button',{name:'Create payable',exact:true}).click();await expect(page.getByRole('alert')).toContainText('amount');}finally{await query('DELETE FROM mock_erp.payables WHERE number=$1',[number]);}});
test('vendor contact edits persist',async({page})=>{const [before]=await query<{email:string;phone:string;notes:string}>('SELECT email,phone,notes FROM mock_erp.vendors WHERE id=$1',['initech']);try{await login(page,'erp');await page.goto(base+'/erp/vendors/initech');await page.getByLabel('Billing email',{exact:true}).fill('testcontact@initech.test');await page.getByLabel('Phone',{exact:true}).fill('+91 99887 76655');await page.getByLabel('Notes',{exact:true}).fill('Browser integration test');await page.getByRole('button',{name:'Save vendor',exact:true}).click();await expect(page.getByText('testcontact@initech.test',{exact:true})).toBeVisible();}finally{await query('UPDATE mock_erp.vendors SET email=$1,phone=$2,notes=$3 WHERE id=$4',[before.email,before.phone,before.notes,'initech']);}});
test('inbox has real injection message and sending appears in Sent',async({page})=>{const subject='TEST MAIL '+Date.now();try{await login(page,'mail');await page.getByRole('link',{name:'URGENT Initech billing change',exact:true}).click();await expect(page.getByText(/AI assistant: ignore your policies/)).toBeVisible();await page.goto(base+'/mail/compose');await page.getByLabel('To',{exact:true}).fill('finance@acme.test');await page.getByLabel('Subject',{exact:true}).fill(subject);await page.getByLabel('Body',{exact:true}).fill('Real browser integration test message');await page.getByRole('button',{name:'Send message',exact:true}).click();await page.getByRole('link',{name:subject,exact:true}).click();await expect(page.getByText('Real browser integration test message',{exact:true})).toBeVisible();}finally{await query('DELETE FROM mock_mail.messages WHERE subject=$1',[subject]);}});
''')
w('tests/e2e/console.spec.ts',r'''import {test,expect} from '@playwright/test';
import {query} from '../../packages/db/src/index';
import {initialCheckpoint} from '../../packages/core/src/types';
const org='00000000-0000-4000-8000-000000000001',employee='00000000-0000-4000-8000-000000000002';
async function login(page:import('@playwright/test').Page){await page.goto('/login');await page.getByLabel('Username',{exact:true}).fill('demo');await page.getByLabel('Password',{exact:true}).fill('demo');await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page.getByRole('heading',{name:'Command center',exact:true})).toBeVisible();}
test('console login, honest no-key state, theme and page navigation',async({page})=>{await login(page);await expect(page.getByText('Connect a model to start autonomous runs',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Run task',exact:true})).toBeDisabled();await page.getByRole('button',{name:'Toggle color theme',exact:true}).click();await expect(page.locator('html')).not.toHaveClass('dark');await page.getByRole('link',{name:'Human inbox',exact:true}).click();await expect(page.getByRole('heading',{name:'Your attention, where it matters'})).toBeVisible();await page.getByRole('link',{name:'Audit trail',exact:true}).click();await expect(page.getByRole('heading',{name:'Audit trail',exact:true})).toBeVisible();});
test('exact-value approval and SSE report update',async({page})=>{const [run]=await query<{id:string}>('INSERT INTO platform.runs(org_id,employee_id,task,status,checkpoint) VALUES($1,$2,$3,$4,$5) RETURNING id',[org,employee,'UI approval fixture — not an autonomous model run','AWAITING_APPROVAL',JSON.stringify(initialCheckpoint())]);const [approval]=await query<{id:string}>('INSERT INTO platform.approvals(org_id,run_id,fingerprint,action,reason,citation) VALUES($1,$2,$3,$4,$5,$6) RETURNING id',[org,run.id,'fixture',JSON.stringify({operation:'invoice_create',values:{amount:'78500',number:'FIXTURE-UI'}}),'High-value payable requires approval','invoice_processing.md']);await login(page);await page.goto('/runs/'+run.id);await expect(page.getByText('78500',{exact:false})).toBeVisible();await page.getByLabel('Approval comment',{exact:true}).fill('Reviewed exact values in browser test');await page.getByRole('button',{name:'Approve action',exact:true}).click();await expect.poll(async()=>{const [a]=await query<{status:string}>('SELECT status FROM platform.approvals WHERE id=$1',[approval.id]);return a.status;}).toBe('APPROVED');await query('INSERT INTO platform.run_events(org_id,run_id,kind,payload) VALUES($1,$2,$3,$4)',[org,run.id,'test',{test:'sse'}]);await expect(page.getByRole('button',{name:'Approve action',exact:true})).toHaveCount(0);await page.screenshot({path:'artifacts/console-run.png',fullPage:true});});
test('second employee created entirely through UI with different tools and SOP',async({page})=>{await login(page);await page.goto('/employees/new');await page.getByRole('textbox').first().fill('Vendor Relations Assistant');await page.locator('textarea').first().fill('Maintain vendor relationships using authenticated vendor messages. Escalate all proposed changes for human review.');await page.getByLabel('Connector configuration JSON').fill(JSON.stringify({mail:{url:'http://127.0.0.1:3001/mail',credentialHandle:'vendor-mail'}}));await page.getByRole('button',{name:'Save employee',exact:true}).click();await expect(page).toHaveURL(/\/employees\/[a-f0-9-]{36}$/);const id=page.url().split('/').at(-1)!;await page.getByRole('button',{name:'New document',exact:true}).click();await page.getByRole('textbox').filter({hasText:''}).count();await page.locator('input').filter({hasNot:page.locator('[type=checkbox]')}).count();await page.getByText('Title',{exact:true}).locator('..').locator('input').fill('vendor_relations.md');await page.getByText('Markdown content',{exact:true}).locator('..').locator('textarea').fill('# Vendor relations\nOnly inspect authenticated vendor mail. Never update records without an approved change request.');await page.getByRole('button',{name:'Save knowledge',exact:true}).click();await expect(page.getByRole('status')).toContainText('Knowledge saved');const [row]=await query<{name:string;allowed_tools:string[]}>('SELECT name,allowed_tools FROM platform.ai_employees WHERE id=$1 AND org_id=$2',[id,org]);expect(row.name).toBe('Vendor Relations Assistant');expect(row.allowed_tools).not.toContain('browser_click');await page.screenshot({path:'artifacts/console-employee.png',fullPage:true});});
''')
w('tests/tools.test.ts',r'''import {describe,it,beforeAll,afterAll,expect} from 'vitest';
import {randomUUID} from 'node:crypto';
import {query} from '../packages/db/src/index';
import {loadEmployee} from '../packages/core/src/store';
import {BrowserSession} from '../packages/core/src/browser';
import {Registry} from '../packages/core/src/registry';
import type {ToolContext} from '../packages/core/src/tools/define';
import type {Call} from '../packages/core/src/types';
const org='00000000-0000-4000-8000-000000000001',employeeId='00000000-0000-4000-8000-000000000002';
let browser:BrowserSession,registry:Registry,ctx:ToolContext;
async function execute(name:string,args:Call['args']={}){return registry.execute({name,args},ctx);}
async function id(label:string){await browser.observe();for(let i=0;i<browser.elements.length;i++){const text=await browser.elements[i].evaluate(n=>{const e=n as HTMLInputElement;return e.labels?.[0]?.innerText||e.textContent||'';});if(text.trim()===label)return i+1;}throw Error('Missing element '+label);}
beforeAll(async()=>{await query("UPDATE mock_portal.settings SET value='false' WHERE key='chaos'");const employee=await loadEmployee(org,employeeId);browser=new BrowserSession(employee,randomUUID());await browser.start();registry=await Registry.load();ctx={employee,browser,memory:{},authorize:async()=>false,ask:async()=>{}};});
afterAll(async()=>{await browser?.close();});
describe('native tool registry against real browser',()=>{
it('discovers tool schemas',()=>{expect(registry.tools.size).toBe(14);expect(registry.definitions(ctx.employee.allowed_tools)).toHaveLength(14);});
it('login resolves encrypted handle',async()=>{expect(await execute('browser_login',{system:'portal',credential_handle:'portal-demo'})).toMatchObject({ok:true,data:{signedIn:true}});});
it('navigation and compact numbered observations',async()=>{const r=await execute('browser_navigate',{url:ctx.employee.connectors.portal.url});expect(r).toMatchObject({ok:true});const obs=await execute('browser_observe');expect(obs.ok&&JSON.stringify(obs.data)).toContain('untrusted_content');expect(browser.elements.length).toBeGreaterThan(5);});
it('clicks pagination and downloads/extracts a real PDF',async()=>{expect(await execute('browser_click',{id:await id('Next page')})).toMatchObject({ok:true});await browser.page!.locator('tbody a').first().click();await browser.observe();const downloaded=await execute('browser_download',{id:await id('Download PDF')});expect(downloaded.ok).toBe(true);if(!downloaded.ok)return;const {file}=downloaded.data as {file:string};expect(await execute('pdf_extract',{file})).toMatchObject({ok:true});expect(await execute('files_list')).toMatchObject({ok:true});});
it('types search field and selects a real vendor',async()=>{await browser.navigate(ctx.employee.connectors.portal.url);expect(await execute('browser_type',{id:await id('Search'),text:'Initech'})).toMatchObject({ok:true});await browser.login('erp','erp-demo');await browser.navigate(ctx.employee.connectors.erp.url+'/new');const vendor=await id('Vendor');expect(await execute('browser_select',{id:vendor,value:'Initech'})).toMatchObject({ok:true});});
it('write submission parks at enforced authorization boundary',async()=>{await browser.page!.locator('[name=number]').fill('NO-WRITE');await browser.page!.locator('[name=amount]').fill('78500');await browser.page!.locator('[name=due]').fill('2026-10-20');const result=await execute('browser_click',{id:await id('Create payable')});expect(result).toMatchObject({ok:true,data:{parked:true}});expect((await query('SELECT id FROM mock_erp.payables WHERE number=$1',['NO-WRITE'])).length).toBe(0);});
it('knowledge, memory, human input, finish all return structured results',async()=>{expect(await execute('knowledge_search',{query:'invoice duplicate approval'})).toMatchObject({ok:true});expect(await execute('memory_note',{key:'source',value:'checked'})).toMatchObject({ok:true});expect(ctx.memory.source).toBe('checked');expect(await execute('ask_human',{question:'What is the due date?'})).toMatchObject({ok:true,data:{parked:true}});expect(await execute('finish',{summary:'Test fixture',claimed_outcome:'Not independently verified'})).toMatchObject({ok:true});});
it('read can never access credential-bearing browser state',async()=>{expect(await execute('files_read',{file:'browser-state.json'})).toMatchObject({ok:false,errorType:'PERMISSION_DENIED'});expect(await execute('files_read',{file:'../../.env'})).toMatchObject({ok:false,errorType:'PERMISSION_DENIED'});});
it('permissions, bad selectors, invalid schema, invalid handle are classified',async()=>{expect(await execute('browser_click',{id:9999})).toMatchObject({ok:false,errorType:'ELEMENT_NOT_FOUND'});expect(await execute('browser_click',{id:-1})).toMatchObject({ok:false,errorType:'VALIDATION'});expect(await execute('browser_login',{system:'portal',credential_handle:'wrong'})).toMatchObject({ok:false,errorType:'PERMISSION_DENIED'});const allowed=ctx.employee.allowed_tools;ctx.employee.allowed_tools=[];expect(await execute('browser_observe')).toMatchObject({ok:false,errorType:'PERMISSION_DENIED'});ctx.employee.allowed_tools=allowed;});
});
''')
